import java.util.*;

class BruteForceMIS {
    int maxWeight(int n, int[][] edges, int[] w) {
        int best = 0;
        for (int mask = 0; mask < (1 << n); mask++) {
            boolean ok = true;
            for (int[] e : edges) {
                if (((mask >> e[0]) & 1) == 1 && ((mask >> e[1]) & 1) == 1) {
                    ok = false; break;   // both endpoints chosen
                }
            }
            if (!ok) continue;
            int sum = 0;
            for (int i = 0; i < n; i++) {
                if (((mask >> i) & 1) == 1) sum += w[i];
            }
            best = Math.max(best, sum);
        }
        return best;
    }
}

