from itertools import product

class BruteForceMIS:
    def max_weight(self, n: int, edges: list[tuple[int, int]], w: list[int]) -> int:
        best = 0
        for mask in range(1 << n):
            if any((mask >> u) & 1 and (mask >> v) & 1 for u, v in edges):
                continue                      # an edge has both ends chosen
            total = sum(w[i] for i in range(n) if (mask >> i) & 1)
            best = max(best, total)
        return best

