import java.util.*;

class TreeMIS {
    private List<List<Integer>> adj;
    private long[] w;
    private long[][] dp;   // dp[node][0]=skip, dp[node][1]=take

    long maxWeight(int n, int root, int[][] edges, long[] weights) {
        adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        this.w = weights;
        dp = new long[n][2];

        // Iterative post-order to avoid stack overflow on a chain of 10^5 nodes.
        int[] parent = new int[n];
        int[] order = new int[n];
        int idx = 0;
        Deque<Integer> stack = new ArrayDeque<>();
        boolean[] seen = new boolean[n];
        stack.push(root); parent[root] = root; seen[root] = true;
        while (!stack.isEmpty()) {            // BFS/DFS order for processing
            int node = stack.pop();
            order[idx++] = node;
            for (int next : adj.get(node)) {
                if (!seen[next]) { seen[next] = true; parent[next] = node; stack.push(next); }
            }
        }
        // Process children before parents: reverse discovery order works for a tree.
        for (int i = n - 1; i >= 0; i--) {
            int node = order[i];
            long take = w[node];
            long skip = 0;
            for (int child : adj.get(node)) {
                if (child == parent[node]) continue;
                take += dp[child][0];
                skip += Math.max(dp[child][0], dp[child][1]);
            }
            dp[node][1] = take;
            dp[node][0] = skip;
        }
        return Math.max(dp[root][0], dp[root][1]);
    }
}

